<script setup>
import {ref,computed,onBeforeUnmount,watch} from 'vue'
const props=defineProps({texto:{type:String,required:true}})
const activo=ref(false),pausado=ref(false),palabraActual=ref(-1),velocidad=ref(0.9),advertencia=ref('')
let utterance=null
const palabras=computed(()=>[...String(props.texto||'').matchAll(/\S+/g)].map(m=>({texto:m[0],inicio:m.index})))
function detener(){if(typeof window!=='undefined'&&'speechSynthesis' in window)window.speechSynthesis.cancel();activo.value=false;pausado.value=false;palabraActual.value=-1;utterance=null}
function escuchar(){if(!('speechSynthesis' in window)){advertencia.value='Tu navegador no admite lectura por voz.';return}detener();const u=new SpeechSynthesisUtterance(props.texto);utterance=u;u.lang='es-ES';u.rate=Number(velocidad.value);let huboBoundary=false;u.onboundary=e=>{if(utterance!==u)return;huboBoundary=true;let idx=-1;for(let i=0;i<palabras.value.length;i++){if(palabras.value[i].inicio<=e.charIndex)idx=i;else break}palabraActual.value=idx};u.onend=()=>{if(utterance===u){activo.value=false;pausado.value=false;palabraActual.value=-1;if(!huboBoundary)advertencia.value='La voz instalada no informa la posición de las palabras. Puedes escuchar el texto, pero el resaltado exacto no está disponible.'}};u.onerror=()=>{if(utterance===u){activo.value=false;pausado.value=false;advertencia.value='No se pudo reproducir la voz en este navegador.'}};activo.value=true;advertencia.value='';window.speechSynthesis.speak(u)}
function pausa(){if(!activo.value)return;if(pausado.value)window.speechSynthesis.resume();else window.speechSynthesis.pause();pausado.value=!pausado.value}
watch(()=>props.texto,detener);onBeforeUnmount(detener)
</script>
<template><section aria-label="Lectura en voz alta" class="lectura-audio"><div class="d-flex flex-wrap gap-2 align-items-center mb-3"><button class="btn btn-primary" @click="escuchar"><i class="fas fa-volume-high" aria-hidden="true"></i> Escuchar</button><button class="btn btn-outline-primary" :disabled="!activo" @click="pausa">{{pausado?'Continuar':'Pausar'}}</button><button class="btn btn-outline-danger" :disabled="!activo" @click="detener">Detener</button><label class="ms-2">Velocidad <select v-model.number="velocidad" class="form-select form-select-sm"><option :value="0.75">Lenta</option><option :value="0.9">Normal</option><option :value="1.1">Rápida</option></select></label></div><p v-if="advertencia" class="alert alert-info">{{advertencia}}</p><div class="lectura-texto"><span v-for="(p,i) in palabras" :key="i" :class="{iluminada:palabraActual===i}">{{p.texto}} </span></div></section></template>
<style scoped>.lectura-texto{font-size:1.24rem;line-height:2.15;white-space:pre-wrap}.lectura-texto span{padding:2px 1px;border-radius:4px}.lectura-texto .iluminada{background:#fde68a;color:#713f12;font-weight:800}</style>
